class ZinvoltConfigFlow(ConfigFlow, domain=DOMAIN):
    """Handle a config flow for Zinvolt."""

    async def async_step_user(
        self, user_input: dict[str, Any] | None = None
    ) -> ConfigFlowResult:
        """Handle the initial step."""
        errors: dict[str, str] = {}

        if user_input is not None:
            client = ZinvoltClient(session=async_get_clientsession(self.hass))
            try:
                token = await client.login(
                    user_input[CONF_EMAIL], user_input[CONF_PASSWORD]
                )
            except ZinvoltAuthenticationError:
                errors["base"] = "invalid_auth"
            except ZinvoltError:
                errors["base"] = "cannot_connect"
            except Exception:  # noqa: BLE001
                LOGGER.exception("Unexpected exception")
                errors["base"] = "unknown"
            else:
                decoded_token = jwt.decode(
                    token, options={"verify_signature": False}
                )
                await self.async_set_unique_id(decoded_token["sub"])
                self._abort_if_unique_id_configured()
                return self.async_create_entry(
                    title=user_input[CONF_EMAIL],
                    data={CONF_ACCESS_TOKEN: token},
                )

        return self.async_show_form(
            step_id="user",
            data_schema=STEP_USER_DATA_SCHEMA,
            errors=errors,
        )
